import glob
import os

# Get all polymorph files
base_dir = os.path.dirname('../CORRAL_WORK_DIR/ml_ujqraq/ml_nitrides_trial_12/polymorph_data/Li3N_polymorphs.json')
polymorph_files = glob.glob(os.path.join(base_dir, '*_polymorphs.json'))

# Consolidate all polymorphs
filtered_data = []

for filepath in polymorph_files:
    composition = os.path.basename(filepath).replace('_polymorphs.json', '')
    try:
        with open(filepath, 'r') as f:
            polymorphs = json.load(f)
            for polymorph in polymorphs:
                polymorph['source_composition'] = composition
            filtered_data.extend(polymorphs)
    except Exception as e:
